package com.example.fdbatch;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.test.context.ActiveProfiles;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;import java.time.*;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
@SpringBootTest @ActiveProfiles("test") @AutoConfigureMockMvc class BatchIntegrationTest {
 @Autowired BatchService service;@Autowired JdbcTemplate jdbc;@Autowired MockMvc mvc;
 @BeforeEach void reset(){for(String t:List.of("event_outbox","consumed_events","scheduler_guard","batch_requests"))jdbc.update("DELETE FROM "+t);}
 @Test void enqueueAndRetry(){String id=UUID.randomUUID().toString();service.request(id,"ACCRUAL",LocalDate.now(),null,"admin1");service.request(id,"ACCRUAL",LocalDate.now(),null,"admin1");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM event_outbox",Integer.class)).isEqualTo(1);}
 @Test void schedulerHasDailyGuard(){service.scheduled(LocalDate.now().minusDays(1));service.scheduled(LocalDate.now().minusDays(1));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM batch_requests",Integer.class)).isEqualTo(1);}
 @Test void conflictingRetryRejected(){String id=UUID.randomUUID().toString();service.request(id,"ACCRUAL",LocalDate.now(),null,"admin1");assertThatThrownBy(()->service.request(id,"ACCRUAL",LocalDate.now().minusDays(1),null,"admin1")).isInstanceOf(IllegalArgumentException.class);}
 @Test void officerCannotTrigger()throws Exception{mvc.perform(get("/api/admin/interest-batches").with(httpBasic("officer1","officer123"))).andExpect(status().isForbidden());mvc.perform(get("/api/admin/interest-batches").with(httpBasic("admin1","admin123"))).andExpect(status().isOk());}
 @Test void payoutRequiresAccount(){assertThatThrownBy(()->service.request(UUID.randomUUID().toString(),"PAYOUT",LocalDate.now(),null,"admin1")).isInstanceOf(IllegalArgumentException.class);}
}
